"0" name="shipping" value="{{ old('shipping',$sale?->shipping??0) }}" class="form-control"></div><div class="col-md-3"><label>Notes</label><input name="notes" value="{{ old('notes',$sale?->notes) }}" class="form-control"></div></div><div class="mt-3"><button class="btn btn-primary">Save Draft</button></div></form>@endsection
@push('scripts')<script>const products=@json($products->map(fn($p)=>['id'=>$p->id,'name'=>$p->name,'price'=>(float)$p->selling_price])->values());const existing=@json(old('items',$sale?->items?->map(fn($i)=>['product_id'=>$i->product_id,'quantity'=>(float)$i->quantity,'unit_price'=>(float)$i->unit_price,'discount'=>(float)$i->discount,'tax'=>(float)$i->tax])->values()->all()??[]));let idx=0;function row(data={}){const tr=document.createElement('tr');tr.innerHTML=`<td><select class="form-select prod" name="items[${idx}][product_id]" required><option value="">Select</option>${products.map(p=>`<option value="${p.id}" ${String(data.product_id)==String(p.id)?'selected':''}>${p.name}</option>`).join('')}</select></td><td><input class="form-control" type="number" step="0.0001" min="0.0001" name="items[${idx}][quantity]" value="${data.quantity??1}" required></td><td><input class="form-control price" type="number" step="0.0001" min="0" name="items[${idx}][unit_price]" value="${data.unit_price??0}" required></td><td><input class="form-control" type="number" step="0.01" min="0" name="items[${idx}][discount]" value="${data.discount??0}"></td><td><input class="form-control" type="number" step="0.01" min="0" name="items[${idx}][tax]" value="${data.tax??0}"></td><td><button type="button" class="btn btn-sm btn-outline-danger">×</button></td>`;tr.querySelector('.prod').onchange=e=>{const p=products.find(x=>String(x.id)===e.target.value);if(p)tr.querySelector('.price').value=p.price};tr.querySelector('button').onclick=()=>tr.remove();document.querySelector('#items-table tbody').appendChild(tr);idx++;}document.getElementById('add-item').onclick=()=>row();(existing.length?existing:[{}]).forEach(row);</script>@endpush
